/**
 * Pioche un profil virtuel au hasard parmi les 1 000 profils disponibles.
 * Possibilité d'exclure un ID pour éviter les doublons successifs.
 */
export function getRandomVirtualProfile(excludeId?: string): VirtualProfile {
  if (!VIRTUAL_PROFILES || VIRTUAL_PROFILES.length === 0) {
    return {
      id: 'bot_0001',
      name: 'Mamadou Diallo',
      country: 'Sénégal',
      countryCode: 'SN',
      flag: '🇸🇳',
      avatar: '🦁',
      level: 12,
      rating: 1450,
      coins: 8500,
      difficulty: 'hard',
    };
  }
  let candidate: VirtualProfile;
  let attempts = 0;
  do {
    const idx = Math.floor(Math.random() * VIRTUAL_PROFILES.length);
    candidate = VIRTUAL_PROFILES[idx];
    attempts++;
  } while (candidate && candidate.id === excludeId && attempts < 5);
  return candidate;
}

export function getVirtualProfileById(id: string): VirtualProfile | undefined {
  return VIRTUAL_PROFILES.find((p) => p.id === id);
}

/**
 * Détecte si un joueur est un profil virtuel / bot.
 * Règle absolue (Cahier des charges) : Les bots ne doivent JAMAIS accepter de demande d'amitié.
 */
export function isVirtualProfileOrBot(idOrName?: string, isBotFlag?: boolean): boolean {
  if (isBotFlag === true) return true;
  if (!idOrName) return false;
  const clean = idOrName.trim();
  if (clean.startsWith('bot_') || clean.startsWith('ai_') || clean.toLowerCase().includes('ordinateur') || clean.toLowerCase().includes('bot')) {
    return true;
  }
  return VIRTUAL_PROFILES.some(
    (p) => p.id === clean || p.name.toLowerCase() === clean.toLowerCase()
  );
}
